func vrfNameBasePath(name string) []any {
	return []any{"vrf", "name", name}
}

// Create sets up the VRFName on VyOS.
func (VRFName) Create(
	ctx context.Context,
	req infer.CreateRequest[VRFNameArgs],
) (infer.CreateResponse[VRFNameState], error) {
	if req.DryRun {
		return infer.CreateResponse[VRFNameState]{
			ID:     req.Inputs.Name,
			Output: VRFNameState{VRFNameArgs: req.Inputs},
		}, nil
	}

	ops := buildVRFNameOps(req.Inputs)
	client := getClient(ctx)
	if err := client.BatchConfigure(ctx, ops); err != nil {
		return infer.CreateResponse[VRFNameState]{},
			fmt.Errorf("configure VRFName %s: %w", req.Inputs.Name, err)
	}
	saveIfEnabled(ctx)

	return infer.CreateResponse[VRFNameState]{
		ID:     req.Inputs.Name,
		Output: VRFNameState{VRFNameArgs: req.Inputs},
	}, nil
}

// Read fetches the current VRFName config from VyOS.
func (VRFName) Read(
	ctx context.Context,
	req infer.ReadRequest[VRFNameArgs, VRFNameState],
) (infer.ReadResponse[VRFNameArgs, VRFNameState], error) {
	client := getClient(ctx)
	base := vrfNameBasePath(req.State.Name)

	data, err := client.ShowConfig(ctx, pathToStrings(base))
	if err != nil {
		if isEmptyConfigError(err) {
			// Tag node exists but has no child properties. Return minimal state.
			args := VRFNameArgs{Name: req.State.Name}
			state := VRFNameState{VRFNameArgs: args}
			return infer.ReadResponse[VRFNameArgs, VRFNameState]{
				ID:     req.State.Name,
				Inputs: args,
				State:  state,
			}, nil
		}
		return infer.ReadResponse[VRFNameArgs, VRFNameState]{},
			fmt.Errorf("read VRFName %s: %w", req.State.Name, err)
	}

	args, err := parseVRFNameConfig(req.State.Name, data)
	if err != nil {
		return infer.ReadResponse[VRFNameArgs, VRFNameState]{},
			fmt.Errorf("parse VRFName %s config: %w", req.State.Name, err)
	}

	state := VRFNameState{VRFNameArgs: args}
	return infer.ReadResponse[VRFNameArgs, VRFNameState]{
		ID:     req.State.Name,
		Inputs: args,
		State:  state,
	}, nil
}

// Update modifies an existing VRFName configuration.
func (VRFName) Update(
	ctx context.Context,
	req infer.UpdateRequest[VRFNameArgs, VRFNameState],
) (infer.UpdateResponse[VRFNameState], error) {
	if req.DryRun {
		return infer.UpdateResponse[VRFNameState]{
			Output: VRFNameState{VRFNameArgs: req.Inputs},
		}, nil
	}

	ops := buildVRFNameUpdateOps(req.State.VRFNameArgs, req.Inputs)
	if len(ops) > 0 {
		client := getClient(ctx)
		if err := client.BatchConfigure(ctx, ops); err != nil {
			return infer.UpdateResponse[VRFNameState]{},
				fmt.Errorf("update VRFName %s: %w", req.Inputs.Name, err)
		}
		saveIfEnabled(ctx)
	}

	return infer.UpdateResponse[VRFNameState]{
		Output: VRFNameState{VRFNameArgs: req.Inputs},
	}, nil
}

// Delete removes the VRFName configuration from VyOS.
func (VRFName) Delete(
	ctx context.Context,
	req infer.DeleteRequest[VRFNameState],
) (infer.DeleteResponse, error) {
	client := getClient(ctx)
	base := vrfNameBasePath(req.State.Name)
	if err := client.Delete(ctx, pathToStrings(base)); err != nil {
		return infer.DeleteResponse{}, fmt.Errorf("delete VRFName %s: %w", req.State.Name, err)
	}
	saveIfEnabled(ctx)
	return infer.DeleteResponse{}, nil
}

